<?php

/*
 * Listing descriptions, written from each listing's own recorded details (its earlier
 * description, category, town, activities, amenities, fee/rate labels, rooms and menu).
 * Applied by ListingDescriptionSeeder, which only updates a row whose id AND name still
 * match. Bulan destinations were added with the owner's explicit approval.
 *
 * Shape: [table => [id => [name, description]]]
 */

return [
    'destinations' => [
        1 => ['Ilawod Beach', 'Ilawod Beach is a beachside leisure spot in Barangay Otavi, Bulan, for swimming, relaxing by the sea and enjoying the coastal scenery. Visitors can try a tandem kayak adventure, and a cabin and the Ilawod Beach House can be rented for longer stays or groups. Free parking, security cameras and a private comfort room are available. An easy beach stop close to the Bulan town area.'],
        2 => ['Camp Hiraya', 'Camp Hiraya is a hilltop camping and viewpoint destination in Barangay Butag, Bulan, with panoramic views of the surrounding landscape and cool breezes. Visitors picnic by day and gather around a bonfire at night, and overnight guests can pitch a tent or use the rooms on site; food orders are served until the evening. Free parking is available. Ideal for nature lovers, families and groups looking for a relaxed outdoor evening.'],
        11 => ['Sabang Park & Beach Resort', 'Sabang Park & Beach Resort in Barangay Otavi, Bulan, is a community park by the sea where families and friends spend time outdoors. Visitors swim, relax and enjoy the open space for leisure and gatherings. A simple, low-cost stop for a family outing near town.'],
        12 => ['Bulan Heritage Museum', 'Bulan Heritage Museum in Barangay Butag presents the history, local artifacts and heritage of the municipality of Bulan. Located in the town proper near Camp Hiraya, it is an indoor stop for culture and history interests that pairs easily with other sights in the area.'],
        13 => ['Bulan Eco Park', 'Bulan Eco Park in Barangay Butag is a nature and recreation park near the town center, close to Camp Hiraya. It is designed for outdoor activities, family picnics and appreciating the local environment. A relaxed, family-friendly stop for nature interests.'],
        42 => ['Apin\'s Place', 'Apin’s Place is a private resort in Bulan for rest, celebrations and gatherings. It is set up for quiet getaways and special occasions with family and friends, so it suits groups planning a private event or a relaxed day away.'],
        43 => ['Cañezal Resort', 'Cañezal Resort is a private pool resort in Villa Las Palmas Subdivision, Barangay Sta. Remedios, Bulan, which describes itself as the first DENR- and municipally approved resort in town. It has an adult swimming pool, a kiddie pool, a roof-deck plunge pool, a second-floor function hall and an air-conditioned pent-room with a TV, Wi-Fi, board games and videoke. Well suited to family outings, private gatherings, seminars and team building.'],
        44 => ['Isabel\'s Resort', 'Isabel’s Resort is a small, cozy pool resort in Bulan for swimming and unwinding. It offers daytime and nighttime entrance, with lower rates for seniors, PWDs and young children, and it is pitched as a private, budget-friendly spot for family gatherings, barkada outings and celebrations.'],
        45 => ['Kapehan sa Bulod', 'Kapehan sa Bulod is a mountain-top destination in Barangay Bonga, Bulan, with sweeping views, fresh mountain air, greenery and sunsets. It has a coffee and dining area in its Camalig, cottages, the distinctive Kapehan Tower, kubolodge accommodation for overnight stays, CCTV, vehicle access and free parking. A scenic stop for coffee, a meal with a view or an overnight stay.'],
        55 => ['Biton Beach', 'Biton Beach, also known as Bitoon White Beach and Resort, is a beach in Bulan with cool sea breezes and wide ocean views. Visitors swim and relax on the sand, with cottages and umbrellas for rent. A relaxed beach day for families and friends.'],
        56 => ['Barbo Ocean View', 'Barbo Ocean View is a coastal viewpoint in Bulan with a clear-water beach below and scenic views of the sea. Visitors come for photos, quiet time and sunset watching, with a comfort room and a sari-sari store on site. A peaceful late-afternoon stop for nature and relaxation interests.'],
        3 => ['Buntay Hills', 'Buntay Hills is a grassy upland in Barangay San Roque, Santa Magdalena, with rolling terrain and steady breezes from the surrounding coast. Locals come here to trek the slopes and watch the sunrise from the ridges, so it suits early-rising nature lovers and light hikers. Expect open, exposed ground with little shade; comfortable shoes and water are worth bringing.'],
        6 => ['Judith Rose Beach Resort', 'Judith Rose Beach Resort is a family beach resort in Santa Magdalena with clear blue water, flowing swimming pools and a quiet coastal setting. Day-tour and overnight guests can rent cabanas, closed kubo cottages, picnic tables or space in the tent camping area, and an event hall is available for gatherings. It works well as a relaxed swimming day for families and groups of friends.'],
        7 => ['Odella Beach Resort', 'Odella Beach Resort is a coastal resort in Barangay San Antonio, Santa Magdalena, set up for group outings and events. Its rentals include family loft-style units, cabanas, a function hall, tent rental and tent-pitching space, and the whole resort can be booked for private occasions. It suits families and barkadas looking for a beach day with facilities.'],
        9 => ['Marahlee Beach Resort', 'Marahlee Beach Resort is a quiet resort on the coast of Barangay San Roque, Santa Magdalena, with a private, tucked-away feel. Guests can take day cottages or kubo huts, use the function hall, or stay overnight in air-conditioned rooms. It is a calm choice for a slow beach day or a short overnight escape.'],
        10 => ['Sorsogon Capitol Park', 'The Sorsogon Provincial Capitol grounds on Rizal Street, Sorsogon City, surround the seat of the provincial government, which bears a historical marker from the National Historical Commission of the Philippines. The landscaped park doubles as a cultural and sports complex, hosting agri-fairs, festivals and Christmas-season attractions. Museo Sorsogon and a José Rizal monument stand on the same grounds, so it pairs naturally with a museum visit for culture and history interests.'],
        14 => ['Museo Sorsogon', 'Museo Sorsogon is the provincial museum inside the Capitol Compound in Sorsogon City, housed in the restored former provincial jail and courthouse. Its ten galleries, curated with the National Historical Commission of the Philippines, trace Sorsogon’s story from early communities through the revolution and the American period, and former inmates’ graffiti is preserved in the old cells. Guided tours, a photo walk of the restored jail and local history talks are offered, and the complex has an amphitheater, a souvenir shop and a coffee shop. A strong indoor stop for culture and history.'],
        15 => ['Rompeolas', 'Rompeolas is Sorsogon City’s bayside promenade along Sorsogon Bay in Barangay Talisay. Families and couples come to stroll the seawall, watch the bay and snack on affordable street food from local vendors; there are bayside restaurants, a children’s playground and a satellite tourism office. It is an easy, low-effort stop, especially pleasant in the late afternoon and evening.'],
        17 => ['Pepita Park', 'Pepita Park is a roadside rest area along the national road in Sorsogon City’s West District, managed by the Department of Public Works and Highways and known for its crab-shaped rest-area building. It sits beside the Bulabog Seafoods Market, which sells fresh, dried and processed seafood overlooking Sorsogon Bay. A short, convenient stop on a road trip for photos, a break and seafood shopping.'],
        20 => ['St. Joseph Parish (Barcelona Church)', 'The Church of St. Joseph in Barcelona is a Spanish colonial-era church built of coral stone, with a historical marker from the National Historical Commission of the Philippines. The ruins of the old Presidencia, the town’s Spanish-era municipal hall, stand across the street, so the two make a compact heritage stop in the town center. Suited to visitors interested in history, architecture and religious heritage; dress respectfully, especially during services.'],
        21 => ['Barcelona Ruins Park', 'Barcelona Ruins Park preserves the remains of the old Presidencia, the town’s Spanish-era municipal building, across the street from the Church of St. Joseph in the town center. Visitors explore the open-air ruins, join a historical walking tour of the poblacion or photograph the stone walls at sunset. A short, easy heritage stop that pairs well with the church.'],
        24 => ['Bulusan Lake', 'Bulusan Lake is an emerald-green crater-side lake at the heart of Bulusan Volcano Natural Park, ringed by dense rainforest. Visitors can take the canopy walk, go kayaking, stand-up paddling or boating, or fish, and there is a coffee shop and restaurant, a massage and spa area and a souvenir shop on site. Service charges recorded for the park include a round-trip shuttle (₱35 per head), eco-guides (₱150 per hour), a paddling guide for kayak or SUP (₱100) and a half-body massage (₱250). One of the province’s key nature and adventure stops; expect forest trails and cool, sometimes wet weather.'],
        25 => ['Bayugin Falls', 'Bayugin Falls is a waterfall in Bulusan surrounded by green bushland. Reaching it involves a forest trek, and at the falls visitors swim in the cold water or rest by the river, making it a good half-day outing for nature and light-adventure interests. Trails can be slippery, so sturdy footwear is advisable.'],
        26 => ['Nagsipit Falls', 'Nagsipit Falls is a tall waterfall in Casiguran wrapped in lush green forest. It is a scenic stop for nature lovers and photographers who want to see a high cascade in a forest setting; swimming and trail conditions should be checked locally before going.'],
        28 => ['Malawmawan Island', 'Malawmawan Island off Barangay Macalaya, Castilla, is a tadpole-shaped island known for colorful coral formations and a long sandbar. Visitors swim, go island hopping, try crystal kayaks, water tricycles and floating mats, or camp overnight with a bonfire. A strong choice for beach, nature and water-activity interests; trips depend on boat transfers and sea conditions.'],
        31 => ['Lola Sayong Eco-Surfing Camp', 'Lola Sayong Eco-Surfing Camp is a community-based surf camp on the beach in Barangay Buenavista, Gubat, run by GubAT Inc. It offers surfing lessons with an instructor and board, kayak rental and snorkeling, and proceeds support community programs including scholarships for its instructors. Bamboo huts and cabins, air-conditioned and fan rooms, a camping area, communal bathrooms, cooking facilities, Wi-Fi, food service and a mangrove nature walk make it suitable for day visits or overnight stays. Ideal for adventure and beach interests.'],
        33 => ['San Benon Resort', 'San Benon Resort in Irosin is a hot spring resort in a green valley setting. It has two hot-water pools, a lukewarm pool, a kiddie pool and a very hot jacuzzi, so visitors can do a hot-and-cold spring circuit or take a short valley nature walk; showers, restrooms and a canteen with short orders are on site. Umbrellas, cottages and cabanas can be rented for day or evening visits. A relaxing stop for families and anyone wanting a warm soak.'],
        34 => ['The Old Houses of Juban', 'Juban is known for its Spanish-era ancestral houses (bahay na bato), several of which can be seen from the Maharlika Highway. The best known is Casa Feliz, built in 1898 for Don Leoncio Grajo and restored with help from the National Historical Commission of the Philippines; it now operates as a bed and breakfast. The other houses are private residences and can only be viewed from the street, so this is a short heritage and architecture stop rather than a guided site.'],
        35 => ['Parola Beach & Lighthouse Station', 'Parola Beach is a white-sand beach on Bagatao Island, Magallanes, reached by boat. Talisay, dangkalan and other beach trees shade the shore for relaxing, and a slowly winding path climbs the hilltop to the historical lighthouse. Combining a boat trip, a swim and the lighthouse walk, it suits beach, nature and history interests; the local government is still developing the site.'],
        36 => ['Bucal-Bucalan Spring Resort', 'Bucal-Bucalan Spring Resort in Barangay Aguada Sur, Magallanes, is a natural spring with large pools fed by spring water, used by locals and visitors for swimming. A simple, refreshing stop for families and anyone looking for a cool-water swim.'],
        37 => ['Subic Beach', 'Subic Beach on Calintaan Island, Matnog, is known for its fine pinkish-white sand and clear water. Visitors walk the pink-sand shore, swim and snorkel, try stand-up paddling, and join fish feeding or fish-interaction trips with snorkeling gear; boats are hired for day tours or overnight stays. Trips are arranged through the Matnog tourism office at the port, so plan around boat schedules and sea conditions. A highlight for beach and nature interests.'],
        39 => ['Panumbagan Marine Sanctuary', 'Panumbagan Sandbar in Pilar Bay is a 5.5-kilometer tamarind-shaped islet that emerges at low tide, with powdery white sand, patches of greenery and, on clear days, views of Mayon and Bulusan volcanoes. It is part of the Pilar Marine Sanctuary, where visitors can try lato (sea grapes) and fresh suwaki (sea urchin), a long-held local delicacy. Visits depend on the tide, so timing matters; best for nature and beach interests.'],
        46 => ['Biyong Cold Spring', 'Biyong Cold Spring in Barangay Alegria, Barcelona, is a cold spring for a refreshing swim, with cottages for rent. From the town center it is signposted along two routes: via Poblacion Norte toward Brgy. Alegria, or via Poblacion Sur toward the Brgy. Cagang crossing; locals can help with directions. A cool, easygoing nature stop for families and groups.'],
        49 => ['Camp Burabod Farmstead', 'Camp Burabod Farmstead in Pinarayik Layog, Barcelona, is a flower-filled farm retreat set in carefully tended gardens with animals around the grounds. It is booked as a Farmer’s Villa overnight stay, with two air-conditioned bedrooms, an attic with a balcony, a kitchen, living and dining areas, an outdoor lanai, a private swimming pool and a fenced front yard. Guests are asked to follow clean-as-you-go and leave-no-trace rules. Best for families or small groups wanting a private garden stay.'],
        50 => ['Colegio Digital Barcelona', 'Colegio Digital Barcelona is a newly built tertiary and post-secondary school focused on digital skills, designed in a Spanish colonial style. Visitors may notice its architecture in town, but it is an educational institution rather than a heritage site or attraction, so it is at most a brief photo stop.'],
        51 => ['Camp Toril Farm & Resort', 'Camp Toril Farm & Resort in Santa Magdalena is a farm-themed resort and camping site with greenery, native animal pens and vegetable gardens. It has a swimming pool, cubo and mushroom cottages, calesa chairs, a mini function hall, videoke, a barbecue and grill area, a bonfire area and camping grounds. A family-friendly choice for a farm outing, a swim or an overnight camp.'],
        52 => ['Balading Beach - Balading Resort', 'Balading Resort on Balading Beach, Santa Magdalena, is a peaceful coastal resort with ocean views and shoreline cottages. Guests can rent open cottages, a big cottage with a room or a bamboo house for a day picnic or overnight stay, with a private comfort room and extra mattresses available. Suited to family gatherings and relaxed beach days.'],
        53 => ['Vintage Bridge', 'Vintage Bridge in Barcelona is an old-style bridge that has become a local recreation spot. Besides sightseeing and photography, visitors can go banana boating, crystal kayaking, recreational kayaking, stand-up paddling and water biking on the water around it. A fun, active stop for groups and families looking for easy water activities.'],
        54 => ['Balay Buhay sa Uma Bee Farm', 'Balay Buhay sa Uma Bee Farm in Bulusan is an agricultural attraction where visitors learn about bee farming and can interact with stingless bees. The farm also has a cold spring pool, Ligwan Cafe, a restaurant and air-conditioned or fan rooms, native kubo huts and duplex rooms for overnight stays. A good fit for nature lovers, families and anyone curious about sustainable farming.'],
        57 => ['Firefly Watching (Ogod River)', 'Firefly watching on the Ogod River in Donsol is an evening boat cruise through mangroves, where thousands of fireflies light up the trees. Local guides share stories about the river and its ecosystem along the way. A calm, unforgettable after-dark nature experience; it takes place at night, so plan dinner and transport around it.'],
        58 => ['Paguriran Lagoon', 'Paguriran in the Bacon District of Sorsogon City is a scenic lagoon and beach with clear blue water, a rocky shoreline and island views. Visitors swim, take photos and relax by the sea, with open cottages for rent and parking for motorcycles, tricycles and cars. A popular coastal stop for nature and beach interests.'],
        59 => ['beach Oasis', 'Beach Oasis in Bulusan is a small beach-and-pool resort with colorful casitas for a cozy staycation. It has beach and pool access, a lifeguard, showers, air-conditioned rooms and family casitas, tables with umbrellas and an open tent area for camping, plus a free light breakfast of brewed coffee and bread for staying guests. Parking and Wi-Fi are limited. A relaxing pick for friends and families.'],
        60 => ['Kipot River', 'Kipot River in Bulusan is a clear, cold river flowing through lush tropical surroundings in the foothills of Mount Bulusan. Visitors cool off in its refreshing water and relax in big or small cottages, and there is parking on site. A peaceful, low-key nature stop for families and groups.'],
        61 => ['16k Blue /pink Roses and Mama Mary statue', 'The 16K Blue/Pink Roses and Mama Mary Statue in Casiguran is a religious site where a statue of the Blessed Virgin Mary stands among blue and pink roses. Visitors come for prayer, reflection and devotion, and to admire the flowers. A quiet stop for pilgrims and culture-minded visitors rather than a recreation spot.'],
        62 => ['Bigaho Eco Park', 'Bigaho Eco Park in Prieto Diaz is reached by a 750-meter walk (about 1.5 kilometers there and back) from the main road through a mangrove forest of natural growth and reforested trees, an important breeding ground for fish and crustaceans. A jeep service runs between the Savemore area and Bigaho. Best for nature lovers who enjoy an easy walk and learning about mangrove ecosystems.'],
        63 => ['Consan\'s Beach Resort', 'Consan’s Beach Resort in Prieto Diaz is a beachfront resort with ocean views, native-style bamboo and wooden kubo huts and open-air seaside seating on the sand. Guests can rent kubo huts, cabanas, papag or tent space for day or overnight stays, and toilets, outdoor sinks and shower rooms are available. Good for a relaxed swim and camp by the sea with family or friends.'],
        64 => ['Sabang Beach', 'Sabang Beach in Prieto Diaz is a quiet coastal spot with sea views, shade trees and free cottages. Visitors swim, relax on the shore and can go boating through the nearby mangrove forest. A simple, budget-friendly beach and nature stop.'],
        65 => ['Gang-Gang Highland', 'Gang-Gang Highland in Bulusan is a viewpoint overlooking the coastline, where turquoise water meets green, coconut-covered hills. Visitors come for the elevated views, photography and fresh air. A short scenic stop for nature lovers and photographers.'],
        66 => ['Kambal Busay', 'Kambal Busay and Hidden Falls in Bulusan are twin cascades surrounded by greenery and rock formations. Visitors enjoy the scenery, explore the surroundings and can swim in designated areas when water conditions allow. A refreshing nature and light-adventure outing; follow local safety guidance at the falls.'],
        67 => ['Casa Cleto', 'Casa Cleto in Casiguran is a countryside pool resort with a native-inspired cottage, a spacious outdoor area and green surroundings. It has a pool, karaoke, fish feeding and fishing, a tent-pitching area, a function hall and a kitchen with basic equipment, and rooms from standard doubles to air-conditioned family and big group rooms. Suited to family outings, group gatherings and overnight stays.'],
        68 => ['Descanso sa Orok', 'Descanso sa Orok in Casiguran is a small resort built around a cold-water swimming pool, with food and drinks available on site. A simple, refreshing swim stop for families and groups.'],
        69 => ['Orok Cold Spring Resort', 'Orok Cold Spring Resort is about 10 kilometers from Casiguran’s town proper, roughly a 20-minute drive from Sorsogon City. Its pool is fed by cold spring water flowing from Bulusan Mountain through untouched forest, which keeps it clear even after heavy rain. Native and concrete cottages, round tables and a function hall for about 30 guests are available. A good cool-water outing for families and groups.'],
        70 => ['Residencia Del hamor', 'Residencia Del Hamor in Casiguran is a resort with an infinity pool and views of the surrounding mountains and coastline. Visitors swim, relax by the pool, rent cottages and can try strawberry picking. A scenic, relaxing stop for families and couples.'],
        71 => ['Sagurong', 'Sagurong in Castilla is a nature spot with clear, cool water, natural swimming pools, rock formations and small cascading streams. Visitors swim in designated areas, picnic and enjoy karaoke, with small and large cottages for rent. A relaxing countryside swim for families and friends.'],
        72 => ['Donsol WhaleShark Tour information', 'Donsol is known as the “Whale Shark Capital of the World”, where visitors can see whale sharks (butanding) by snorkeling or diving with them or watching them surface from a boat. Tours start with registration, and boats and snorkeling gear are rented for the trip. Sightings are best from February to April and depend on the season and sea conditions. A once-in-a-lifetime wildlife and adventure experience.'],
        73 => ['Vitton Beach Resort', 'Vitton Beach Resort in Donsol is a beachfront resort near the whale shark interaction area, with a restaurant, rooms, a swimming pool, cottages, picnic tables and sunset views over the water. Visitors swim and picnic, and it can serve as a base for whale shark trips. Suited to families and groups on a beach day or overnight stay.'],
        74 => ['Amor Farm Beach Resort', 'Amor Farm Beach Resort in Donsol is a seaside resort with a sandy beach and sea views. Guests rent small or large kubo huts or air-conditioned rooms, walk the shore, take photos, watch the sunrise or sunset and swim when the sea is calm. A relaxed beach stop or overnight stay for families.'],
        75 => ['AGM BeachFront Resort', 'AGM BeachFront Resort in Donsol is a simple, quiet beachfront resort away from city noise, where visitors swim and relax by the sea. A low-key option for a restful beach day.'],
        76 => ['Rizal Beach', 'Rizal Beach in Gubat is a white-sand beach lined with coconut and fruit trees. Visitors swim, go boating and beachcombing, or camp with a bonfire, and a resthouse and shore cottages (Balai units) are available. A classic beach day for nature and relaxation interests.'],
        77 => ['Gubat Tourism Hub "Mini Siargao"', 'The Buenavista Tourism Hub in Gubat, nicknamed “Mini Siargao”, is a lively coconut-lined beachfront with surfing (with local instructors), picnics and even skateboarding. Its market stalls sell local food and products from homegrown businesses, and the area lights up in the evening with food stalls. Great for beach, food and adventure interests, especially late afternoon into the evening.'],
        78 => ['Agoho Forest', 'Agoho Forest Beach in Gubat is a wide sandy shore shaded by tall agoho trees. Visitors stroll, picnic, camp and swim when the sea is safe, with family and open cottages, kubo huts and a tent area for rent. A shady, relaxing beach for families and campers.'],
        79 => ['The Escape', 'The Escape in Gubat is a beachfront resort with an infinity pool, a bar and grill restaurant and rooms with balconies and ocean views. Guests can try crystal kayaking, ATV rides and surfing, and rooms have fast Wi-Fi, TVs and private bathrooms with hot showers, with bathtubs in family rooms. Suits couples and families wanting an active beach stay.'],
        80 => ['401K Resort', '401K Resort in Irosin is a family pool resort with three swimming pools, slides and a kids’ playground, plus billiards, table tennis, a basketball court, a volleyball area and movies you can watch while swimming. Cottages can be rented and karaoke is available. A lively, family-friendly day out.'],
        81 => ['PRASADA Resort', 'PRASADA Resort in Irosin is a swimming resort with a pool, cottages and fan-cooled kubo huts, open for both morning and night swimming. A simple recreation stop for families and groups.'],
        82 => ['Vida Guest Resort', 'Vida Guest Resort in Irosin has three big swimming pools, videoke and a private cabin house with a jacuzzi. Visitors swim and enjoy karaoke, and guests can stay in the cabin house. Suited to families and groups looking for a pool day or a private overnight stay.'],
        83 => ['Tangke Nature Spring', 'Tangke Nature Spring in Juban is a countryside spring with cool water and green surroundings. Visitors swim in designated areas, grill food at the ihawan, sing videoke and rent cottages, with small stores on site. A refreshing nature stop for families and groups.'],
        84 => ['Gibalon Shrine', 'Gibalon in Magallanes is believed to be the site of the first Catholic Mass in Luzon, celebrated by Fray Alonso Jimenez and Fray Juan Orta in 1569, making the old fishing village near the Ginangra River the first Christian settlement on the island. Augustinian friars, accompanied by Captain Enrique de Guzman, planted the cross and built the first chapel in Luzon here. A meaningful stop for history and religious-heritage interests.'],
        85 => ['Ladladan Hills', 'Ladladan Hills in Matnog is a stretch of rolling green hills with wide views of the countryside. Visitors hike and explore the slopes and take panoramic photos. A good outdoor stop for hikers and nature lovers; the hills are open terrain with little shade.'],
        86 => ['Mila Beach Resort', 'Mila Beach Resort in Matnog is a laid-back seaside resort with cottages, tables, room accommodations and karaoke. Visitors stroll the shore, picnic and swim when the sea is safe. A relaxed beach day or overnight option for families.'],
        87 => ['Villa Kulintang', 'Villa Kulintang in Pilar is a private two-floor beachfront villa that blends rustic Filipino architecture with European design and an eco-friendly approach. Guests arrive by outrigger boat and have the whole villa, with a private pool, bay views, a kitchen and barbecue grill, air conditioning and Wi-Fi; island hopping and whale shark trips can be requested. It is a private stay for couples or small groups rather than a public attraction.'],
        88 => ['Caparos Paradise Resort', 'Caparos Paradise Resort in Castilla is a coastal resort with clear water, a sandy shore and striking rock formations. Visitors swim when the sea is calm, picnic and photograph the rocks, with cottages, a cabana and a bamboo house for day use or overnight stays and a sari-sari store on site. A scenic beach stop for nature and relaxation interests.'],
        89 => ['Balogo Sprts Complex', 'Balogo Sports Complex in Sorsogon City is a public sports facility for athletics, training, competitions and community events. Visitors may jog, exercise or watch local games. It is a recreation venue rather than a historical or sightseeing attraction.'],
        90 => ['Bacon Manito Road', 'The Bacon–Manito Road winds through the hills of Sorsogon City’s Bacon District toward Manito, Albay, past rolling green slopes and wide coastal views. It is a favorite scenic drive and stopover for cyclists, motorcycle riders and road-trippers, with roadside viewpoints and parking along the shoulder. Best enjoyed in daylight for photography.'],
        91 => ['Halabang Baybay', 'Halabang Baybay, meaning “long beach”, is a gray-sand shoreline in the Bacon District with calm morning water and an open view of Sorsogon Bay. Locals come for weekend picnics, swimming and sunset walks, with a picnic area, cottages for rent and parking. An easy, relaxed beach stop.'],
        92 => ['Hanamor Spring Resort', 'Hanamor Spring Resort in the Bacon District is a garden resort with a swimming pool, A-frame cabins and carefully kept grounds: terraced flower beds, a green arch walkway and a Japanese-style garden corner. Shaded paths, picnic tables and photo spots make it a relaxing day trip for families and groups.'],
        93 => ['Lebanon Beach', 'Lebanon Beach is a quiet beach on the Pacific-facing coast of the Bacon District, with wide sand, rolling waves and an uncrowded, rustic feel. Visitors relax on the beach, swim when conditions allow and take photos, with cottages and parking available. A good choice for a slow day by the sea.'],
        94 => ['Ozi Camp', 'Ozi Camp is a seaside resort in Tiris, Bacon District, with a swimming pool and slide, nipa huts and cottages under tall coconut palms, and a grassy lawn running to the seawall with views across the bay. Visitors swim and picnic by the sea, and air-conditioned rooms are available for overnight stays. A relaxed family resort day or overnight.'],
        95 => ['Pagol Beach', 'Pagol Beach in the Bacon District is a long stretch of light sand backed by forest, with clear shallow water and rock formations at one end that glow at sunset. Visitors enter through Geern’s Resort, where nipa cottages are reserved and resort guests can use paid parking. Great for swimming and sunset viewing.'],
        96 => ['The woods mahongay Farm', 'The Woods is a mahogany farm in the Bacon District, with rows of tall mahogany trees, an herb garden and plant displays at the entrance. Visitors walk under the trees, rest in hammocks beneath canvas shades and share meals in the nipa-roofed dining pavilion. A quiet, shaded nature stop for relaxation.'],
        97 => ['Tiya Heide’s Beach Camp', 'Tiya Heide’s Beach Camp beside Pagol Beach is a palm-shaded camp with nipa huts for groups of up to about 12, picnic tables and a fine-sand shore with clear, shallow water. On clear days Mayon Volcano rises across the bay, especially at sunset. Visitors swim, play badminton, lounge in hammocks or camp overnight on the beachfront; a restroom is available.'],
        98 => ['LagoLand Resort', 'LagoLand Resort in Barcelona is a family resort built around a large curved pool with fountains, shaded by sail canopies and lit up at night. There is a kiddie pool, a playground with swings and a climbing frame, nipa huts, a covered pavilion and an outdoor shower area. Ideal for families with children.'],
        99 => ['Villa Lucia', 'Villa Lucia in Bulusan is a garden resort with a pool, cottages and green surroundings at the foot of the Bulusan highlands. Visitors swim and stroll the garden, and it makes a convenient stop between the town’s lake, falls and coast.'],
        100 => ['Wood’s Camp', 'Wood’s Camp is a forest campsite in Bulusan near Palogtoc Falls, shaded by tall trees and cooled by mountain air. It has a tent area for day visits or overnight pitching, restrooms and a bonfire area, and suits campers and hikers exploring the Bulusan Volcano Natural Park area.'],
        101 => ['St. JamesThe greater Parish Church', 'The parish church of St. James the Greater stands in Bulusan’s town center near the shore and is the heart of the town’s religious life. Visitors can attend Mass or view the church, and the restored Punta Diamante watchtower stands beside it, so the two make an easy heritage stop.'],
        102 => ['Punta Diamante', 'Punta Diamante is the site of Bulusan’s old stone watchtower, one of the “Mga Moog ng Bulusan” built to guard the town against raids during the Spanish colonial era. The restored octagonal tower stands beside the St. James the Greater Parish Church, with a historical marker at the churchyard gate and Stations of the Cross in the churchyard. Stairs inside lead to the upper levels, with views over the church grounds toward the sea.'],
        103 => ['Palogtoc falls', 'Palogtoc Falls is a cool, clear waterfall in the forests of Bulusan with a natural pool at its base. A short walk along a forest trail leads to the falls, where visitors swim and rest in the cottages. A refreshing nature stop that pairs well with nearby Wood’s Camp.'],
        104 => ['Station of the Cross', 'The Station of the Cross in Casiguran is a hillside pilgrimage path with the fourteen Stations leading up the slope. It draws devotees especially during Holy Week, and the climb ends at a viewpoint over the town and Sorsogon Bay. Expect a steady uphill walk.'],
    ],

    'accommodations' => [
        16 => ['Casa Buenas Hotel', 'Casa Buenas Hotel is a hotel in Bulan with air-conditioned Standard and Deluxe rooms, each with a private bathroom, toiletries and a work desk; Deluxe rooms add a sofa, dining area and, in some rooms, a television and mini refrigerator. The property has free Wi-Fi, parking, room service, a garden and a kitchen. A comfortable overnight base in Bulan for couples, families and other travelers.'],
        17 => ['Caree Boutique Hotel', 'Caree Boutique Hotel opened in December 2016 as the first hotel in Bulan. Its 30 rooms include family, standard premium and standard rooms, and a function hall seats up to 150 people for seminars and events. Free Wi-Fi, air conditioning, breakfast, hot showers, room service and parking make it a practical base for exploring Bulan.'],
        18 => ['Karl\'s Hotel', 'Karl’s Hotel is an affordable hotel in central Bulan with Standard, Deluxe and Suite rooms. Rooms are air-conditioned with private bathrooms, hot showers, TVs, free Wi-Fi and kitchenettes, and higher categories add balconies, mini refrigerators, sofas and dining areas. The hotel has a 24-hour front desk, a restaurant, breakfast, laundry service, family rooms and accessibility facilities, making it a convenient overnight base.'],
        19 => ['Vivi\'s Hotel and Resto Bar', 'Vivi’s Hotel and Resto Bar in Bulan combines a small hotel with an evening resto bar. Its Standard rooms are air-conditioned, with private bathrooms, TVs, balconies, dining areas and free Wi-Fi. A relaxed place to stay for travelers who like having food and drinks on site.'],
        20 => ['Balay Talisay', 'Balay Talisay is a home-style guesthouse along the coastal promenade in Sorsogon City, with Filipino architectural touches, garden views and air-conditioned rooms. It offers free Wi-Fi, room service, a kitchen, family rooms and parking, and is pet-friendly. A homey base close to the Rompeolas baywalk.'],
        21 => ['Isla de Blas', 'Isla de Blas on Calintaan Island, Matnog, is a water resort with cottages on stilts above lagoon waters, an on-site restobar, kayak rentals and viewdeck trails. Rooms are air-conditioned, with family rooms and hot showers, and the beach is right there. A memorable overnight stay for island trips around Matnog, reached by boat.'],
        22 => ['Elysia Beach Resort', 'Elysia Beach Resort is a beachfront resort in Barangay Pangpang, Donsol, within walking distance of the Donsol Whale Shark Interaction area. It has a restaurant and bar, an outdoor swimming pool, air-conditioned and family rooms, breakfast, free Wi-Fi and parking, and access to diving and whale shark trips. A convenient base for a Donsol whale shark itinerary.'],
        23 => ['Lim\'s Resort', 'Lim’s Resort is a resort in Barangay Bagsangan, Irosin, in the town’s spring and mountain area. It has a swimming pool, a garden, air-conditioned and family rooms with hot showers and TVs, and parking, and it is pet-friendly. A restful base for exploring Irosin’s hot springs and the Bulusan area.'],
        24 => ['Siama Surf Resort', 'Siama Surf Resort, also called the Artist’s Village, is a boutique beachfront resort on the Rizal–Buenavista beach stretch in Gubat. It has a swimming pool, a restaurant, room service, breakfast, family rooms, a kitchen and free Wi-Fi, with direct beach access. A stylish base for surfers and couples visiting Gubat’s beaches.'],
        25 => ['Birbeck Lodge', 'Birbeck Lodge is a simple lodging option in Santa Magdalena for travelers, backpackers and overnight guests. A practical place to sleep while exploring the town’s beach resorts.'],
        26 => ['Altarejos Homestay', 'Altarejos Homestay in North Poblacion, Juban, is a local homestay for visitors exploring the town’s heritage houses, springs and parks. It offers air-conditioned and family rooms, free Wi-Fi, room service, a kitchen, a garden and hot showers, and it is pet-friendly. The map pin is approximate.'],
        27 => ['Kendi\'s Beach Garden', 'Kendi’s Beach Garden in Barangay Buenavista, Gubat, is a beachfront cottage-and-garden stay close to Gubat’s surf camps and beach breaks. It has a swimming pool, a garden, air-conditioned and family rooms, a kitchen, free Wi-Fi and parking, and it is pet-friendly. A laid-back base for surfing and beach days; the map pin is approximate.'],
        28 => ['Modesta Resort', 'Modesta Resort in Barangay Monbon, Irosin, is a Bali-inspired nature resort on a large property surrounded by mountains and greenery. It has cottages, private villas, mini-pools, picnic areas and several fresh mountain-water pools, plus a restaurant, breakfast, family rooms and accessibility facilities. A relaxing overnight stay for families and couples; the map pin is approximate.'],
        29 => ['Elizabeth\'s hostel', 'Elizabeth’s Hostel is a budget hostel in Poblacion, Magallanes, near the public market and port. It offers air-conditioned and family rooms, free Wi-Fi, kitchen facilities, hot showers and a roof deck with a view. A practical, affordable base for boat trips around Magallanes.'],
        30 => ['Uno\'s Krib', 'Uno’s Krib is a budget guesthouse along the diversion road in Pilar, with air-conditioned rooms, private balconies and mountain views. Complimentary coffee, free Wi-Fi, a kitchen and parking are available, and it is pet-friendly. A simple, affordable overnight stop in Pilar.'],
        31 => ['Arcadia Crystal Subic Beach Resort', 'Arcadia Crystal Subic Beach Resort is a beachfront island resort on Subic Beach, Matnog, with air-conditioned guest rooms, cabanas, duplexes and ocean-facing outdoor seating. A convenient overnight stay for visitors who want to wake up on the pink-sand beach, reached by boat from Matnog.'],
        32 => ['Pilar Marina Inn', 'Pilar Marina Inn is a coastal inn in the center of Pilar with air-conditioned and family rooms, free Wi-Fi, a 24-hour front desk, room service, breakfast and an on-site café. It is pet-friendly and has accessibility facilities. A dependable base for Panumbagan Sandbar and other Pilar trips.'],
        33 => ['Star Beach Casitas', 'Star Beach Casitas in Barangay Peñafrancia, Santa Magdalena, is a private seaside retreat with air-conditioned casitas, swimming pool access and beach access. Free Wi-Fi, family rooms and parking are available, and it is pet-friendly. A quiet overnight stay for couples and families.'],
        34 => ['Midz Homestay', 'Midz Homestay in Barangay Hidhid, Matnog, is a family homestay near the highway and local schools. It offers rooms with kitchen privileges, breakfast, free Wi-Fi, a garden and parking, and it is pet-friendly. A practical base for travelers passing through Matnog or catching boats from the port.'],
        35 => ['Villa Isabel Hotel', 'Villa Isabel Hotel in Sorsogon City is a hotel complex with rooms, outdoor swimming pools, garden function venues and an in-house restaurant serving local dishes. It has a 24-hour front desk, breakfast, room service, family rooms and accessibility facilities. A full-service base in the provincial capital.'],
        36 => ['Burabod Seaside resort', 'Burabod Seaside Resort is a seaside resort in Prieto Diaz offering overnight stays by the coast. Details on rooms and facilities are limited, so it is best to confirm what is available before booking.'],
        37 => ['Recidencia Del Hamor Full View', 'Recidencia Del Hamor Full View is a 37-room resort in Barangay Bon-ot, Sorsogon City, with an outdoor pool, a restaurant, room service and free parking. A buffet breakfast is served daily, and family rooms, Wi-Fi and beach access are available. A comfortable resort base in Sorsogon City.'],
        38 => ['Severosa Resort', 'Severosa Resort in Prieto Diaz is a resort stay with a swimming pool, a garden, free Wi-Fi and parking, and it is pet-friendly. A quiet overnight option in Prieto Diaz.'],
        39 => ['La Verde', 'La Verde in Prieto Diaz is a resort-style stay with a swimming pool, a garden, beach access, air-conditioned and family rooms, breakfast and a kitchen. Free Wi-Fi, parking, laundry service and accessibility facilities are available, and it is pet-friendly. A well-equipped overnight base on the Prieto Diaz coast.'],
        40 => ['Highland garden resort', 'Highland Garden Resort is a garden resort along the Bacon–Sawanga–Prieto Diaz Road in Prieto Diaz, with a swimming pool, air-conditioned and family rooms, free Wi-Fi and parking. It is pet-friendly. A green, restful place to stay between Bacon and Prieto Diaz.'],
        41 => ['Arthur’s Resort', 'Arthur’s Resort is a resort stay in Barangay Lupi, Prieto Diaz. Details on rooms and facilities are limited, so confirm what is available before booking.'],
        42 => ['CDL HOTEL', 'CDL Hotel is a hotel in Barangay Brilliante, Prieto Diaz, with a swimming pool, a garden, air-conditioned and family rooms, a kitchen, room service and free Wi-Fi. It has accessibility facilities and is pet-friendly. A convenient overnight base in Prieto Diaz.'],
        43 => ['Blue Tupaz Inn & Restobar', 'Blue Tupaz Inn & Restobar is an inn with a restobar in Prieto Diaz. Details on rooms and facilities are limited, so confirm what is available before booking.'],
        44 => ['Mai’s Hotel and Resort', 'Mai’s Hotel and Resort in the Bacon District of Sorsogon City combines hotel rooms with a resort pool and garden. It offers air-conditioned and family rooms, breakfast, a kitchen, free Wi-Fi, parking and accessibility facilities, and it is pet-friendly. A handy base for the Bacon District’s beaches.'],
        45 => ['EKOLEE HOMETEL', 'EKOLEE Hometel is a home-style hotel on Magsaysay Street, Barangay Maningcay De Oro, Prieto Diaz, with air-conditioned rooms, hot showers, a kitchen, TVs, free Wi-Fi and parking. A simple, practical overnight stay in Prieto Diaz.'],
        46 => ['RedDoorz @Paul hanz Tourist Inn and Events Place', 'RedDoorz @ Paul Hanz Tourist Inn and Events Place is a budget inn with an events venue in Barangay Balogo, Sorsogon City. It offers air-conditioned and family rooms, non-smoking floors, free Wi-Fi, room service, laundry service, a kitchen, parking and accessibility facilities, and it is pet-friendly. An affordable base in the city.'],
    ],

    'food_beverages' => [
        1 => ['Una Pizzeria', 'Una Pizzeria in Sorsogon City is a well-regarded restaurant known for brick-oven pizzas and European dishes. A good choice for an Italian meal or a change from local fare.'],
        2 => ['Balay Buhay sa Uma', 'Balay Buhay sa Uma in Barangay San Roque, Bulusan, is a farm-to-table restaurant at an eco-retreat, serving Bicolano cuisine made from local produce. It pairs naturally with a visit to the farm and Bulusan’s nature spots.'],
        3 => ['Butanding Bar and Restaurant (Giddy\'s Place)', 'Butanding Bar and Restaurant at Giddy’s Place, a popular dive resort in Donsol, serves fresh seafood and drinks. A convenient meal stop before or after whale shark and diving trips.'],
        4 => ['Linda\'s', 'Linda’s is a local eatery in Gubat known for its halo-halo and Bicol express. A good pick for affordable Filipino comfort food and a cold dessert after the beach.'],
        5 => ['Casa Luna', 'Casa Luna in Barangay Buenavista, Irosin, is a restaurant and events place serving local food, with catering for gatherings. A practical meal stop in Irosin, especially for groups.'],
        8 => ['Test Restaurant - Revision 2', 'Sorsogon Flavors Restaurant & Café is a casual dining spot in Bulusan offering traditional Filipino dishes, Bicolano specialties, drinks and desserts for families, friends and visitors.'],
        9 => ['Bentornato', 'Bentornato Restaurant & Café is a seaside Filipino restaurant on Zuniga Street, Bulan, with a rooftop terrace overlooking the bay where acoustic music plays at sunset. Its menu includes pancit canton, baked mussels, sweet-and-sour fish, kangkong with tofu and native desserts like hinagom and ube halaya, served on an open patio and at a café counter. A moderately priced choice for dinner with a view.'],
        10 => ['Ning’s Restaurant', 'Ning’s Restaurant is a budget-friendly, home-style Filipino eatery on the Bulan Airport Road in Barangay Gate. Its menu covers rice meals and soups such as Bicol express, sinigang na baboy and pork adobo, with halo-halo for dessert. A dependable stop for an affordable local breakfast or lunch.'],
        11 => ['Yolanda’s garden', 'Yolanda’s Garden is a relaxed garden-style dining spot in Bulan with open-air tables among the plants. Its moderately priced menu features Filipino favorites and grilled dishes such as inihaw na liempo, laing and pancit canton by the bilao, with fresh buko juice. Suited to slow afternoon meals and family gatherings.'],
        12 => ['Dragon House', 'Dragon House on V. Zuniga Street, Bulan, serves Chinese-Filipino food in family-size platters made for groups and celebrations. Its menu includes Yang Chow fried rice, sweet-and-sour pork, pancit canton and siomai, at moderate prices.'],
        13 => ['Lola Feling Restaurant', 'Lola Feling Restobar on Gullaba Street in Bulan’s town center is a cozy, budget-friendly Filipino restaurant and bar decorated with bamboo lamps and tropical-leaf murals. By day it serves home-style meals like sinigang na hipon, Bicol express, crispy pata, chicken inasal and buttered garlic shrimp; in the evening its bar suits drinks with friends over pulutan like chicharon bulaklak and shanghai rolls.'],
        14 => ['YUKIMICHI Ramen House', 'YUKIMICHI Ramen House near the Barangay San Vicente welcome arch in Bulan serves Japanese-style comfort food at moderate prices. The menu runs from tantanmen ramen, katsudon, gyudon and katsu curry to takoyaki, okonomiyaki, gyoza, karaage and baked sushi, with fruit shakes. The town’s go-to spot for a Japanese meal.'],
        15 => ['Sip Spot Cafe', 'Sip Spot Cafe in Zone 3, Bulan, is a small, budget-friendly neighborhood café serving coffee such as iced caramel macchiato, classic milk tea and light snacks like clubhouse sandwiches and cookies. A laid-back stop for a merienda or a break.'],
        16 => ['Mama Vacion\'s Restaurant, Bar, and Grill\'', 'Mama Vacion’s Bar & Grill in Zone 3, Bulan, is a bamboo-built restaurant with woven walls, string lights and a long hardwood table for big groups. It serves grilled favorites and pulutan such as pork barbecue, sizzling sisig, grilled tuna belly and calamares with cold drinks, and a tea counter at the entrance offers milk tea and coffee. A moderately priced spot for group dinners.'],
        17 => ['Kusina ni nanay', 'Kusina ni Nanay in Barangay Sta. Teresita, Bulan, is a budget-friendly garden restaurant with native-style dining in thatched kubo huts and a bamboo hall. It serves home-cooked Filipino food such as daily viands with rice, tinolang manok, pinangat and maja blanca. A quiet place for family meals and celebrations.'],
        18 => ['Cryptea Cafe', 'Cryptea Cafe on C. Gotladera Street, Zone 2, Bulan, is a budget-friendly milk tea café serving drinks like wintermelon milk tea, brown sugar boba milk and iced Americano with quick bites such as fries. An easy merienda stop while exploring the town center.'],
        19 => ['Bubbly Cup café -bulan', 'Bubbly Cup Café in Zone 2, Bulan, on the street leading to the Bulan Boulevard, offers milk tea, frappes and snacks to take along for a sunset walk by the bay. Its budget-friendly menu includes Okinawa milk tea, cookies-and-cream frappe, chicken poppers and lemonade.'],
        20 => ['Hiraya’s', 'Hiraya’s Resto & Grill on C. Gotladera Street, Zone 5, Bulan, has served the town since 2022 with the tagline “Where every bite takes you home.” Its cozy dining room serves all-day breakfast silog meals such as porksilog, tocilog and longsilog, along with grilled plates, burgers and halo-halo, plus party trays for gatherings. Moderately priced and good for breakfast or a casual meal.'],
        21 => ['TeaStreet', 'TeaStreet in Zone 5, Bulan, in front of SLI KRAMS, is a budget milk tea and refreshment stop serving taro milk tea, mango fruit tea, matcha frappe and snacks like cheese sticks. A quick merienda stop for students and passers-by.'],
        22 => ['Chef W Bulan', 'Chef W Bulan on V. Zuniga Street is a food shop and catering service known for party trays and celebration food. Its offerings include crispy pata, lechon belly, lumpia shanghai, Filipino spaghetti and pancit meal boxes, for pickup or prepared for events. Best for takeout and group orders rather than sit-down dining.'],
        23 => ['LALU’s Brick & Brew cafe', 'LALU’s Brick & Brew Café on T. De Castro Street, Zone 8, Bulan, pairs coffee and blended drinks with Filipino comfort rice meals such as embutido, bacsilog, chicken ala king and beef tapa. It also bakes muffins and oat bars and prepares packed meals for events. A moderately priced spot for breakfast, lunch or merienda.'],
        24 => ['The Habitat', 'The Habitat in Barangay Beguin, Bulan, is a rustic campground café among coconut and banana trees, with thatched huts, bamboo fences and open lawns where goats and chickens roam. Its kitchen serves Filipino comfort food such as the Habitat rice bowl, nachos, iced coffee and banana bread, and the grounds also host camping, swimming, live bands and events. A relaxed nature-side meal stop.'],
        25 => ['El Jardin resto Bar', 'El Jardin on T. De Castro Street, Bulan, is a rooftop garden resto bar with bougainvillea arches and open-air tables overlooking the bay, a favorite spot at sunset. Its menu includes grilled chicken wings, pork sisig, kinilaw na isda and buckets of iced tea, with party platters for celebrations. A moderately priced choice for a sunset dinner.'],
        26 => ['Kapehan sa Bulod', 'Kapehan sa Bulod is a budget-friendly hilltop café and restaurant in Barangay Butag, Bulan, with open-air pavilions and nipa-roofed huts overlooking the green hills. Its menu centers on chicken wings in buffalo, salted, sweet soy and teriyaki flavors, in 4-, 8- and 12-piece servings. A scenic stop for merienda or a casual meal with a view.'],
    ],

    'retail_shops' => [
        2 => ['Bulan Public Market', 'Bulan Public Market is the town’s central market, with vendors selling fresh seafood, produce and local Sorsogon handicrafts. Tourists can browse for handmade crafts and local goods to take home, and see the daily life of the town.'],
        6 => ['Matnog Port Public Market', 'Matnog Port Public Market, by the port, has vendors selling fresh seafood such as crabs and squid alongside local souvenirs. A convenient stop for snacks and souvenirs before or after island hopping from Matnog.'],
        7 => ['PiliNuts Pasalubong Center', 'PiliNuts Pasalubong Center in Matnog sells pili nut products and locally made delicacies, including roasted and sweetened pili nuts, pili candies and other pasalubong favorites. A good stop for edible souvenirs from Sorsogon to bring home.'],
        8 => ['Gibalon Heritage Pasalubong & Delicacies', 'Gibalon Heritage Pasalubong & Delicacies in Barangay Siuton, Magallanes, is a souvenir store near the town’s historical sites selling packaged Bicolano treats such as glazed pili nuts, mazapan de pili and tablea discs. A handy pasalubong stop after visiting Gibalon.'],
        9 => ['Leslie Pili Nut Products', 'Leslie Pili Nut Products in Sorsogon City specializes in pili nut goods: glazed pili, roasted salted pili, marzapan de pili, pili tart and pili oil products. A focused stop for pili-based pasalubong.'],
        10 => ['Tia Berning\'s Store & Native Handicrafts', 'Tia Berning’s Store & Native Handicrafts in Sorsogon City sells handwoven abaca slippers, native bayong bags, abaniko fans, coin purses and other handcrafted keepsakes. A good stop for native craft souvenirs.'],
        11 => ['Bagol Craft & Souvenir Shop', 'Bagol Craft & Souvenir Shop in the Bacon District makes crafts, home décor, kitchenware and trinkets from polished coconut shells (bagol). A distinctive stop for handmade souvenirs.'],
        12 => ['Bagatao Island Shellcrafts & Collectibles', 'Bagatao Island Shellcrafts & Collectibles on Bagatao Island, Magallanes, sells handmade shell jewelry, wind chimes and ocean-themed home décor. A natural souvenir stop on a trip to Parola Beach and the lighthouse.'],
        13 => ['Manay Jo\'s Handicraft & Native Goods', 'Manay Jo’s Handicraft & Native Goods in Santa Magdalena is an artisan store specializing in handwoven abaca products, decorative mats, native storage baskets and handcrafted bayong bags. A good stop for authentic native crafts.'],
        14 => ['San Sebastian Dried Fish & Coastal Produce', 'San Sebastian Dried Fish & Coastal Produce in Barangay San Sebastian, Santa Magdalena, is a coastal stall selling dried fish such as tuyo and danggit, dried squid and local seafood catches. A good place to pick up dried seafood as pasalubong.'],
        15 => ['Juana\'s Handicrafts & Souvenirs', 'Juana’s Handicrafts & Souvenirs near Matnog Port is a gift shop with keychains, shell crafts, ref magnets, T-shirts and handwoven abaca products for departing travelers. A convenient last-minute souvenir stop before leaving Matnog.'],
    ],
];
